EOF
    } > "$readme"
}

# ---------------------------------------------------------------------
# honesty_gate — the assembly-time half of plugingen's listing gate.
# ---------------------------------------------------------------------

honesty_gate() {
    local out="$1"

    # (a) + (c) THE shared checker, in Go, over EVERY file of the final
    #     assembled tree: no savings claim (literal phrases AND the
    #     %-near-efficiency-vocabulary pattern class), and the verbatim
    #     prerequisite sentence in every README — including the root
    #     landing page this script authors. One owner:
    #     plugins/plugingen/honesty.go, which plugingen's own tests run
    #     over the generated tree.
    command -v go >/dev/null 2>&1 \
        || die "the honesty gate needs the Go toolchain (it runs plugins/plugingen -honesty-check, the one owner of the rule)"
    (cd "$REPO_ROOT" && go run ./plugins/plugingen -honesty-check "$out") \
        || die "the assembled tree failed the honesty gate (see above)"

    # (b) Every manifest description that exists carries it too. Gemini's
    #     manifest has no description field (the documented schema has
    #     none), which is why its README states it instead.
    local manifest
    for manifest in \
        "$out/.claude-plugin/marketplace.json" \
        "$out/$CLAUDE_PLUGIN_DIR/.claude-plugin/plugin.json" \
        "$out/$CODEX_PLUGIN_PATH/.codex-plugin/plugin.json" \
        "$out/opencode/package.json" \
        "$out/kimi.plugin.json" \
        "$out/openclaw.plugin.json" \
        "$out/.devin-plugin/plugin.json" \
        "$out/.factory-plugin/marketplace.json" \
        "$out/$DROID_PLUGIN_PATH/.factory-plugin/plugin.json" \
        "$out/.qoder-plugin/marketplace.json" \
        "$out/$QODER_PLUGIN_PATH/.qoder-plugin/plugin.json" \
        "$out/cowork/$PLUGIN_DIR/manifest.json"
    do
        node - "$manifest" "$PREREQ_SENTENCE" <<'EOF'
const fs = require('fs');
const [, , filePath, sentence] = process.argv;
const doc = JSON.parse(fs.readFileSync(filePath, 'utf8'));
// A CATALOG (anything with a plugins array) describes the marketplace
// itself at the top level — that line is a shelf label, not a listing, so
// only its ENTRY descriptions are gated. Everything else is a single
// listing and its own description is what a user reads.
const descriptions = [];
if (Array.isArray(doc.plugins)) {
  for (const entry of doc.plugins) {
    if (typeof entry.description === 'string') descriptions.push(entry.description);
  }
} else if (typeof doc.description === 'string') {
  descriptions.push(doc.description);
}
if (descriptions.length === 0) {
  console.error(`${filePath}: no description to gate`);
  process.exit(1);
}
for (const d of descriptions) {
  if (!d.includes(sentence)) {
    console.error(`${filePath}: a description does not state the binary prerequisite verbatim:\n  ${d}`);
    process.exit(1);
  }
}
EOF
    done

}

# ---------------------------------------------------------------------
# Entry points
# ---------------------------------------------------------------------

if [ "$SELF_CHECK" -eq 1 ]; then
    assert_source_completeness
    a=$(mktemp -d)
    b=$(mktemp -d)
    trap 'rm -rf "$a" "$b"' EXIT
    rmdir "$a" "$b"
    assemble "$a"
    assemble "$b"
    if ! diff -r "$a" "$b"; then
        die "assembly is NOT deterministic — two runs produced different trees"
    fi
    if [ "$VERSION" = "$SELF_CHECK_FIXTURE_VERSION" ]; then
        echo "assemble-plugins-repo: deterministic — two runs at $VERSION (FIXTURE version; --self-check publishes nothing, pass a real tag to assemble a release) are byte-identical"
    else
        echo "assemble-plugins-repo: deterministic — two runs at $VERSION are byte-identical"
    fi
    echo "assemble-plugins-repo: $(find "$a" -type f | wc -l) files, honesty gate passed"
    exit 0
fi

assemble "$OUT_DIR"

echo "assemble-plugins-repo: assembled the superbasedapp/plugins tree at $VERSION"
echo
(cd "$OUT_DIR" && find . -type f | sort | sed 's|^\./|  |')
echo
echo "  Claude Code : /plugin marketplace add superbasedapp/plugins"
echo "  Codex       : codex plugin marketplace add superbasedapp/plugins"
echo "  Gemini CLI  : gemini extensions install https://github.com/superbasedapp/plugins"
echo
echo "NOTHING WAS PUBLISHED. This script writes one directory and nothing else."
